Module PQATKB.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation RSEGS := Asan.M.loaded_segments.
Abbreviation mem := (word -> option byte).

Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells).
Hypothesis LY : PMA.layout L C.
Let LYa := PMA.ly_as0 L C LY.
Section KitB.
Variable HI : asan_iface.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Lemma amcpyB LB FF LK cr Aw sp scr fr u m (fx0 : FPState) Ra Ma modela Kc o n q (bs : list byte) ra :
  In (u, m) LB -> u <= o -> o + n <= u + m -> 0 < n <= 96 ->
  ri_inv HI LB FF LK cr Aw Ma (vml_of modela) -> L5CA.amodel_ok Aw modela -> L5CA.astk ar Ma sp scr -> PMSPA.accA Ma o n -> L5.defined Ma o n ->
  0 <= fr -> fr + 2560 <= scr -> (sp - fr) mod 16 = 0 ->
  getr Ra (reg 10) = Z_to_bv 64 o -> getr Ra (reg 11) = Z_to_bv 64 q -> getr Ra (reg 12) = Z_to_bv 64 n -> getr Ra (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr Ra (reg 1) = Z_to_bv 64 ra -> ra mod 2 = 0 -> 0 <= ra < 2 ^ 64 -> getr Ra (reg 2) = Z_to_bv 64 (sp - fr) -> Kc [] ->
  PMSPA.accA Ma q n -> 0 <= q -> q + n <= 2 ^ 47 -> app_rng ar q n -> (forall i, 0 <= i < n -> aclient L ar LB FF (sp - fr) 2560 (q + i)) ->
  rdn RSEGS Ma (Z_to_bv 64 q) (Z.to_nat n) = Some bs -> (o + n <= q \/ q + n <= o) ->
  (forall Rb Mb modelb, getr Rb (reg 10) = Z_to_bv 64 o -> regs_preserved Ra Rb ->
     (forall i, 0 <= i < n -> exists v, (nth_error bs (Z.to_nat i) = Some (Z_to_bv 8 v) /\ 0 <= v < 256) /\ byte_at Mb (o + i) v) ->
     (forall a, 0 <= a < 2 ^ 64 -> aclient L ar LB FF (sp - fr) 2560 a -> ~ (o <= a < o + n) -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) ->
     (forall a, sp - fr - 2560 <= a < sp - fr -> Mb (Z_to_bv 64 a) <> None) ->
     L5.defined Mb o n -> model_rt modela modelb -> L5CA.amodel_ok Aw modelb -> ri_inv HI LB FF LK cr Aw Mb (vml_of modelb) ->
     srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx0) Rb ra Mb modelb) Kc) ->
  srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx0) Ra 0x7ebbc Ma modela) Kc.
Proof.
  intros INB Ho Hon Hn HHa AMa ASTKa ACCa DEFa Hfr Hfr' F16 Ra10 Ra11 Ra12 Ra4 Ra1 Hra Hra' Ra2 Ka ACCq Hq0 Hq1 APPq CLq RDq APq KC.
  pose proof (HAJ.aior_memcpy _ _ _ _ _ HIok) as MS. unfold amemcpy_spec, amemcpy_spec_at, amem_pre, amem_post in MS.
  rewrite (L5A.aly_segs L C LYa), (L5A.aly_memcpy L C LYa), (L5A.aly_scr_mem L C LYa), (L5A.aly_img_lo L C LYa), (L5A.aly_img_hi L C LYa) in MS.
  assert (U2 : bv_unsigned (getr Ra 2%bv) = sp - fr).
  { rewrite L5K.rl2, Ra2. pose proof ASTKa as (_ & SLO & SHI & SPT & _).
    pose proof (HAJ.aior_wf _ _ _ _ _ HIok _ _ _ _ _ _ _ HHa) as (_ & _ & FSAPP & FSCEIL & _). unfold app_mem, FS_BYTES in FSAPP, FSCEIL.
    apply L5.unsigned_lit. lia. }
  assert (OB : 0 <= u /\ u + m <= 2 ^ 47).
  { pose proof (HAJ.aior_wf _ _ _ _ _ HIok _ _ _ _ _ _ _ HHa) as (WB & _). destruct (WB (u, m) INB) as ((B0 & B1 & B2 & B3 & B4 & _) & _). cbn [fst snd] in *.
    pose proof ASTKa as (_ & SLO & SHI & SPT & _). lia. }
  unfold PMSPA.cfg. apply (MS fx0 Ra Ma modela LB FF LK cr Aw o q n bs Kc); clear MS.
  - split; [exact HHa|]. split; [exact (proj1 AMa)|]. split; [exact (proj2 AMa)|].
    split; [rewrite L5K.rl10; exact Ra10|]. split; [rewrite L5K.rl12; exact Ra12|]. split; [lia|].
    split; [rewrite L5K.rl4; exact Ra4|]. split; [rewrite L5K.rl1, Ra1; apply Hoare.ret_ok_even; rewrite L5.unsigned_lit by lia; exact Hra|].
    split. { rewrite U2. apply (L5SAR.astack_ok_of_astk L ar C LYa Ma Ma sp scr fr 2560 ASTKa (fun x X => X)); [lia| lia| lia| exact F16]. }
    split. { intros a Ha. apply ACCa. lia. }
    split. { intros i Hi. rewrite U2. apply (L5SAR.block_client L ar LB FF _ _ u m (o + i) INB). lia. }
    split. { intros i k Hi Hk. pose proof (L5C.writable_of_defined RSEGS Ma o n DEFa ltac:(lia) ltac:(lia)) as W. apply W; lia. }
    split; [exact Ka|]. apply (L5SAR.app_rng_block L ar C HI HIok LB FF LK cr Aw Ma _ u m o n HHa INB); lia.
  - rewrite L5K.rl11. exact Ra11.
  - exact ACCq.
  - lia.
  - exact APPq.
  - intros i Hi. right. rewrite U2. apply CLq. exact Hi.
  - exact RDq.
  - intros _. exact APq.
  - intros Rb Mb modelb Rb10 RPb BYTES PRES SDEFb RTb MIb HHb. rewrite U2 in PRES, SDEFb. rewrite L5K.rl1, Ra1.
    apply (KC Rb Mb modelb); [rewrite <- L5K.rl10; exact Rb10| exact RPb| exact BYTES| exact PRES| exact SDEFb| | exact RTb| | exact HHb].
    + intros i Hi. destruct (BYTES i Hi) as (v & _ & Bv). unfold byte_at in Bv. rewrite Bv. discriminate.
    + split; [rewrite (L5LZ.model_rt_halted _ _ RTb); exact (proj1 AMa)| exact MIb].
Qed.
End KitB.

Section KitS.
