(* [comment removed for export] *)
Lemma amsetB LB FF LK cr Aw sp scr fr u m (fx0 : FPState) Ra Ma modela Kc o n ra :
  In (u, m) LB -> u <= o -> o + n <= u + m -> 0 < n <= 96 ->
  ri_inv HI LB FF LK cr Aw Ma (vml_of modela) -> L5CA.amodel_ok Aw modela -> L5CA.astk ar Ma sp scr -> PMSPA.accA Ma o n -> L5.defined Ma o n ->
  0 <= fr -> fr + 2560 <= scr -> (sp - fr) mod 16 = 0 ->
  getr Ra (reg 10) = Z_to_bv 64 o -> getr Ra (reg 11) = Z_to_bv 64 0 -> getr Ra (reg 12) = Z_to_bv 64 n -> getr Ra (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr Ra (reg 1) = Z_to_bv 64 ra -> ra mod 2 = 0 -> 0 <= ra < 2 ^ 64 -> getr Ra (reg 2) = Z_to_bv 64 (sp - fr) -> Kc [] ->
  (forall Rb Mb modelb, getr Rb (reg 10) = Z_to_bv 64 o -> regs_preserved Ra Rb -> PM.zeros_at Mb o n ->
     (forall a, 0 <= a < 2 ^ 64 -> aclient L ar LB FF (sp - fr) 2560 a -> ~ (o <= a < o + n) -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) ->
     (forall a, sp - fr - 2560 <= a < sp - fr -> Mb (Z_to_bv 64 a) <> None) ->
     L5.defined Mb o n -> model_rt modela modelb -> L5CA.amodel_ok Aw modelb -> ri_inv HI LB FF LK cr Aw Mb (vml_of modelb) ->
     srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx0) Rb ra Mb modelb) Kc) ->
  srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx0) Ra 0x7f058 Ma modela) Kc.
Proof.
  intros INB Ho Hon Hn HHa AMa ASTKa ACCa DEFa Hfr Hfr' F16 Ra10 Ra11 Ra12 Ra4 Ra1 Hra Hra' Ra2 Ka KC.
  pose proof (HAJ.aior_memset _ _ _ _ _ HIok) as MS. unfold amemset_spec, amem_pre, amem_post in MS.
  rewrite (L5A.aly_segs L C LYa), (L5A.aly_memset L C LYa), (L5A.aly_scr_mem L C LYa) in MS.
