Lemma msetB_post LB FF LK cr Aw sp scr fr u m (Ma Mb : mem) modela o n :
  ri_inv HI LB FF LK cr Aw Ma (vml_of modela) -> L5CA.astk ar Ma sp scr -> In (u, m) LB -> u <= o -> o + n <= u + m -> 0 <= fr -> fr + 2560 <= scr ->
  (forall a, 0 <= a < 2 ^ 64 -> aclient L ar LB FF (sp - fr) 2560 a -> ~ (o <= a < o + n) -> Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a)) ->
  (forall a, sp - fr - 2560 <= a < sp - fr -> Mb (Z_to_bv 64 a) <> None) -> L5.defined Mb o n ->
  L5SAR.ek L ar LB FF sp scr [(o, n)] Ma Mb /\ L5SAR.dk L ar LB FF sp scr Ma Mb /\ L5CA.astk ar Mb sp scr.
Proof.
  intros HH ASTK INB Hou Hon Hfr Hfr' PRES SDEF DEF. pose proof ASTK as (A16 & SLO & SHI & SPT & SD & SUP).
  assert (OB : 0 <= u /\ u + m <= ahl_ceil ar).
  { pose proof (HAJ.aior_wf _ _ _ _ _ HIok _ _ _ _ _ _ _ HH) as (WB & _). destruct (WB (u, m) INB) as ((B0 & B1 & B2 & B3 & B4 & _) & _). cbn [fst snd] in *. lia. }
  split. { apply (L5SAR.ek_mem L ar LB FF sp scr (sp - fr) 2560 (fun a => o <= a < o + n) [(o, n)] Ma Mb PRES); [lia| lia|].
           intros a Hc Ho X. apply (Ho (o, n)); [left; reflexivity| unfold L5.in_rng; cbn [fst snd]; lia]. }
  split. { apply (L5SAR.dk_mem L ar LB FF sp scr (sp - fr) 2560 (fun a => o <= a < o + n) Ma Mb PRES SDEF); [| | lia| lia].
           - intros a Ha. replace a with (o + (a - o)) by lia. apply DEF. lia.
           - intros a. destruct (L5SAR.rng_dec a o (o + n)) as [X|X]; [left; exact X| right; exact X]. }
  apply (L5SAR.astk_after_eq L ar C HI HIok LB FF LK cr Aw Ma Ma Mb _ sp _ (sp - fr) 2560 HH ASTK (fun x X => X)).
  - intros a Ha Hs Hns. apply PRES. exact Ha. apply L5SAR.stack_client. exact Hs. exact Hns. lia.
  - exact SDEF.
  - lia. - lia. - lia.
Qed.
